R.append((7785022,
("Crema de fruta de naranja para untar", "Nuestra versión de la mermelada: una gelatina agridulce de naranja llena de fruta, pero con mucha menos azúcar. Excelente para pan tostado, muffins y scones, o para rellenar pasteles.", "12", "56 g",
 ["3 naranjas medianas", "200 ml de agua hirviendo", "1 sobre de 23 g de gelatina de naranja sin azúcar en polvo"],
 ["Ralle finamente la cáscara de las naranjas y ponga la ralladura en una jarra con el agua hirviendo.", "Incorpore el sobre de gelatina hasta que se disuelva por completo.", "Quite la parte blanca de la naranja y luego separe los gajos, dejando la parte blanca. Pique en trozos grandes y agregue a la jarra.", "Exprima el centro de la naranja para sacar todo el jugo y agréguelo a la jarra.", "Deje enfriar, luego pase a un frasco grande, mezcle, cierre bien y refrigere durante al menos 2 a 3 horas. Guarde en el refrigerador: se conserva durante 5 días."],
 ["Pique la mermelada con una cuchara antes de comerla para que sea más fácil de untar.", "Para una versión vegetariana o vegana, use un agente gelificante a base de algas sin sabor, y use concentrado sin azúcar y edulcorante.", "@FV"], []),
("معجون البرتقال الفاكهي للدهن", "نسختنا من مربى البرتقال: جيلي برتقال حلو ومر مليء بالفاكهة، لكنه أقل بكثير في السكر. رائع مع التوست والمافن والسكونز، أو لحشو الكعك.", "12", "56 جم",
 ["3 حبات برتقال متوسطة", "200 مل ماء مغلي", "1 كيس 23 جم بلورات جيلي البرتقال الخالي من السكر"],
 ["ابشر قشر البرتقال برفق وبشكل ناعم، ثم ضع القشر المبشور في إبريق مع الماء المغلي.", "أضف كيس الجيلي وحرّك حتى يذوب تمامًا.", "أزل الجزء الأبيض من البرتقال، ثم افصل الفصوص تاركًا الجزء الأبيض. قطّعها تقطيعًا خشنًا وأضفها إلى الإبريق.", "اعصر قلب البرتقالة لاستخراج أي عصير، ثم أضفه إلى الإبريق.", "اتركه ليبرد، ثم ضعه في برطمان كبير، وقلّبه، ثم أغلقه وضعه في الثلاجة لمدة ساعتين إلى 3 ساعات على الأقل. احفظه في الثلاجة - يبقى صالحًا لمدة 5 أيام."],
 ["قطّع المربى بالملعقة قبل تناوله ليسهل دهنه.", "للحصول على نسخة نباتية، استخدم عامل تكثيف مصنوعًا من الأعشاب البحرية وغير منكّه، واستخدم شراب مركّز خالٍ من السكر ومحليًا.", "@FV"], [])))
