R.append((7786545,
("Estofado irlandés y colcannon", "Un delicioso estofado invernal servido con col y puré de papa.", "4", "483 g",
 ["1 cucharadita de aceite de oliva", "1 cebolla grande, pelada y cortada en trozos grandes", "450 g de cordero magro, en cubos", "650 g de papas, peladas y cortadas en trozos grandes", "2 zanahorias, peladas y cortadas en trozos grandes", "1 cubito de caldo", "1 chorrito de salsa Worcestershire", "1 cucharada de polvo para salsa de carne (gravy)", "1 buena pizca de hierbas secas mixtas", "650 g de camotes, pelados y picados", "2 cucharadas de leche semidescremada", "1 cucharada de margarina poliinsaturada reducida en grasa", "pimienta negra recién molida", "media col de Saboya, finamente rebanada", "1 manojo de cebollines, picados en trozos grandes"],
 ["Caliente el aceite en una cazuela grande que resista el fuego directo, agregue las cebollas y el cordero y fría de 3 a 4 minutos, hasta que la carne esté dorada.", "Agregue el resto de los ingredientes del estofado y suficiente agua para cubrir el contenido. Deje que hierva, tape y cocine a fuego muy lento de 1½ a 2 horas, hasta que la carne esté tierna.", "Mientras tanto, prepare el colcannon. Ponga los camotes en una olla grande con agua hirviendo y cocine de 10 a 12 minutos, hasta que estén tiernos. Escúrralos, macháquelos con la leche y la margarina, y sazone con abundante pimienta negra.", "Cueza la col en una olla con agua hirviendo hasta que esté tierna, escúrrala e incorpore una cuarta parte al puré junto con los cebollines.", "Sirva el resto de la col con el estofado y el colcannon."],
 ["Puede usar carne de res, cerdo o venado en lugar de cordero.", "Si usa carne grasosa, cocine el platillo el día anterior, refrigere y, una vez frío, retire la grasa de la superficie antes de recalentar.", "Instrucciones para congelar: Se puede congelar una vez cocido. Descongele en el refrigerador o en el microondas y recaliente hasta que esté muy caliente por completo.", "@FV"], []),
("يخنة أيرلندية وكولكانون", "يخنة شتوية لذيذة تُقدَّم مع الملفوف وهريس البطاطس.", "4", "483 جم",
 ["1 ملعقة صغيرة زيت زيتون", "1 حبة بصل كبيرة، مقشرة ومقطعة إلى قطع كبيرة", "450 جم لحم ضأن خالٍ من الدهن، مقطع إلى مكعبات", "650 جم بطاطس، مقشرة ومقطعة إلى قطع كبيرة", "2 حبة جزر، مقشرة ومقطعة إلى قطع كبيرة", "1 مكعب مرق", "رشة صلصة ورسترشير", "1 ملعقة كبيرة مسحوق مرق اللحم (غريفي)", "رشة وافرة من الأعشاب المجففة المشكلة", "650 جم بطاطا حلوة، مقشرة ومقطعة", "2 ملعقة كبيرة حليب نصف خالي الدسم", "1 ملعقة كبيرة سمن نباتي (مارجرين) مخفض الدسم غني بالدهون المتعددة غير المشبعة", "فلفل أسود مطحون طازجًا", "نصف حبة ملفوف سافوي، مقطعة إلى شرائح رفيعة", "1 حزمة بصل أخضر، مفرومة فرمًا خشنًا"],
 ["سخّن الزيت في طنجرة كبيرة تتحمل اللهب المباشر، وأضف البصل ولحم الضأن وقلّبهما لمدة 3–4 دقائق حتى يتحمر اللحم.", "أضف باقي مكونات اليخنة وماءً يكفي لتغطية المحتويات. اتركها حتى تغلي، وغطِّ الطنجرة واتركها على نار هادئة جدًا لمدة 1½–2 ساعة حتى يلين اللحم.", "وفي هذه الأثناء، حضّر الكولكانون. ضع البطاطا الحلوة في قدر كبير من الماء المغلي واتركها تنضج لمدة 10–12 دقيقة حتى تلين. صفِّها واهرسها مع الحليب والسمن النباتي، وتبّلها بكمية وافرة من الفلفل الأسود.", "اسلق الملفوف في قدر من الماء المغلي حتى يلين، وصفِّه وقلّب ربعه في الهريس مع البصل الأخضر.", "قدّم باقي الملفوف مع اليخنة والكولكانون."],
 ["يمكنك استخدام لحم البقر أو لحم الخنزير أو لحم الغزال بدلًا من لحم الضأن.", "إذا استخدمت لحمًا دهنيًا، فاطهِ الطبق في اليوم السابق وضعه في الثلاجة، وعندما يبرد أزل الدهن من سطح الطبق قبل إعادة التسخين.", "تعليمات التجميد: مناسب للتجميد بعد الطهي. ذوّبه في الثلاجة أو الميكروويف وأعد تسخينه حتى يصبح ساخنًا جدًا في كل أجزائه.", "@FV"], [])))
