R.append((7793516,
("Biryani de pollo", "Olvídese de la comida para llevar y elija una cena sabrosa, todo en uno, llena de sabor pero baja en calorías.", "4", "421 g",
 ["2 cucharaditas de aceite de girasol", "1 cebolla grande, picada", "300 g de pechuga de pollo sin piel, cortada en trozos", "1 pimiento rojo, picado", "1 zanahoria, en cubos", "8 champiñones, en rodajas", "1 berenjena, picada en cubos", "1 cucharada de pasta de curry (suave, media o picante)", "1 cucharada de pasas sultanas", "250 g de arroz basmati integral, enjuagado con agua fría", "800 ml de agua hirviendo", "100 g de chícharos congelados, descongelados", "1 puñado de cilantro fresco, picado", "1 cucharada de aceite de oliva"],
 ["Ponga el aceite de girasol en una olla con la cebolla, cocine durante 2 minutos, luego agregue el pollo y revuelva de 3 a 4 minutos más.", "Agregue el pimiento rojo, la zanahoria, los champiñones y la berenjena, y cocine 5 minutos más, revolviendo con regularidad.", "Incorpore la pasta de curry y las pasas sultanas y mezcle bien.", "A continuación, agregue el arroz a las verduras y mezcle bien. Luego agregue el agua hirviendo y mezcle de nuevo. Deje que hierva y luego baje el fuego a bajo. Tape y cocine durante 11 minutos.", "Apague el fuego y deje reposar 5 minutos sin quitar la tapa.", "Agregue los chícharos, el cilantro y el aceite de oliva al arroz. Mezcle bien y sirva."],
 ["Para una versión vegetariana, agregue un pimiento adicional, una calabacita picada y una lata de garbanzos.", "También puede usar pavo, camarones o salmón en lugar de pollo.", "También puede sustituir parte de la carne con frijoles: están llenos de proteína y fibra, y además son más económicos.", "Si no tiene berenjena, simplemente agregue más champiñones y zanahorias.", "Tampoco es necesario usar cilantro; quedará igual de sabroso sin él.", "Si no tiene arroz a la mano, ¿por qué no probar quinoa o cuscús integral?", "Se puede congelar una vez cocido. Luego descongele en el refrigerador y recaliente hasta que esté muy caliente por completo.", "@FV"], []),
("برياني الدجاج", "تخلَّ عن الوجبات الجاهزة واختر عشاءً لذيذًا متكاملًا في طبق واحد، غنيًا بالنكهة وخفيفًا في السعرات الحرارية.", "4", "421 جم",
 ["2 ملعقة صغيرة زيت عباد الشمس", "1 حبة بصل كبيرة، مفرومة", "300 جم صدر دجاج منزوع الجلد، مقطع إلى قطع", "1 حبة فلفل أحمر، مفرومة", "1 حبة جزر، مقطعة إلى مكعبات", "8 حبات فطر، مقطعة إلى شرائح", "1 حبة باذنجان، مقطعة إلى مكعبات", "1 ملعقة كبيرة معجون كاري (خفيف أو متوسط أو حار)", "1 ملعقة كبيرة زبيب سلطانة", "250 جم أرز بسمتي بني، مشطوف بالماء البارد", "800 مل ماء مغلي", "100 جم بازلاء مجمدة، مذابة", "حفنة كزبرة خضراء طازجة، مفرومة", "1 ملعقة كبيرة زيت زيتون"],
 ["ضع زيت عباد الشمس في قدر مع البصل، واطهه لمدة دقيقتين، ثم أضف الدجاج وقلّب لمدة 3–4 دقائق أخرى.", "أضف الفلفل الأحمر والجزر والفطر والباذنجان، واطهِ لمدة 5 دقائق أخرى مع التحريك باستمرار.", "أضف معجون الكاري والزبيب واخلط جيدًا.", "بعد ذلك، أضف الأرز إلى الخضار واخلط جيدًا. ثم أضف الماء المغلي واخلط مرة أخرى. اتركه حتى يغلي، ثم اجعل النار هادئة. غطِّ القدر واطهِ لمدة 11 دقيقة.", "أطفئ النار واتركه لمدة 5 دقائق دون رفع الغطاء.", "أضف البازلاء والكزبرة الخضراء وزيت الزيتون إلى الأرز. اخلط جيدًا وقدّمه."],
 ["للحصول على نسخة نباتية، أضف حبة فلفل إضافية وحبة كوسا مفرومة وعلبة حمص.", "يمكنك أيضًا استخدام الديك الرومي أو الروبيان أو السلمون بدلًا من الدجاج.", "يمكنك أيضًا استبدال جزء من اللحم بالفاصولياء، فهي غنية بالبروتين والألياف وأرخص أيضًا.", "إذا لم يتوفر لديك باذنجان، فما عليك سوى إضافة المزيد من الفطر والجزر.", "ولا يلزمك استخدام الكزبرة الخضراء أيضًا، فسيكون الطبق لذيذًا بالقدر نفسه بدونها.", "إذا لم يتوفر لديك أرز، فلماذا لا تجرب الكينوا أو الكسكس من الحبوب الكاملة.", "مناسب للتجميد بعد الطهي. ثم ذوّبه في الثلاجة وأعد تسخينه حتى يصبح ساخنًا جدًا في كل أجزائه.", "@FV"], [])))
